<script setup>
import { useBackupContext } from '../../composables/useBackupContext.js';
import { incompleteBackupLabel, offlineStorageSummary, storageMountState } from '../../taskCenter.js';
import { statusLabel } from '../StatusBadge.js';
import OrderBusinessFields from './OrderBusinessFields.vue';
const { isAdmin, selectedOrder, assets, supplements, supplementUpload, downloadOrder, uploadSupplement, downloadSupplement, restoreSelectedOrder, storageState } = useBackupContext();
function uploadFile(file) { uploadSupplement({ target: { files: [file.raw] } }); }
</script>
<template>
  <el-card v-if="selectedOrder" class="order-detail" shadow="never">
    <template #header><div class="detail-header"><div><h3>{{ selectedOrder.orderCode || selectedOrder.sourceOrderId }} <el-tag v-if="selectedOrder.backupMode === 'METADATA_SIMULATION'" type="warning" effect="plain">模拟备份</el-tag> <el-tag v-if="incompleteBackupLabel(selectedOrder)" type="warning" effect="dark">文件可能不完整</el-tag></h3><span class="muted">创建于 {{ selectedOrder.orderCreatedAt || '-' }}</span></div><div class="toolbar-actions"><el-button :disabled="!storageState(selectedOrder).canDownload" @click="downloadOrder()"><el-icon><Download /></el-icon>下载订单包</el-button><el-button v-if="isAdmin" type="primary" :disabled="selectedOrder.backupMode === 'METADATA_SIMULATION' || !storageState(selectedOrder).canDownload" @click="restoreSelectedOrder"><el-icon><Upload /></el-icon>线上恢复</el-button></div></div></template>
    <el-alert v-if="selectedOrder.backupMode === 'METADATA_SIMULATION'" title="当前为模拟备份：ZIP 内保留 manifest 和零字节文件占位符，可下载验证，不可用于线上恢复。" type="warning" show-icon :closable="false" />
    <el-alert v-else-if="incompleteBackupLabel(selectedOrder)" :title="`${incompleteBackupLabel(selectedOrder)}；已备份 ${selectedOrder.assetCount ?? assets.length} 个真实文件。`" type="warning" show-icon :closable="false" />
    <el-alert v-if="!storageState(selectedOrder).canDownload" :title="storageState(selectedOrder).message" type="warning" show-icon :closable="false" />
    <el-alert v-else-if="selectedOrder.storageDiagnosticReason" :title="`副本诊断：${selectedOrder.storageDiagnosticReason}`" type="warning" show-icon :closable="false" />
    <el-alert v-else-if="selectedOrder.storageLocation" :title="`订单包位置：${selectedOrder.storageLocation.storageVolumeName || '未命名卷'} · ${statusLabel(selectedOrder.storageLocation.storageTier)} · ${statusLabel(selectedOrder.storageLocation.mountStatus)}${selectedOrder.storageLocation.archiveNote ? ' · 封存：' + selectedOrder.storageLocation.archiveNote : ''}`" type="info" show-icon :closable="false" />
    <OrderBusinessFields :value="selectedOrder.displayJson || selectedOrder.orderRawJson" />
    <el-row :gutter="24"><el-col :span="14"><h4>关联文件 <el-tag size="small" effect="plain">{{ assets.length }} 个</el-tag></h4><el-empty v-if="!assets.length" description="暂无关联文件" :image-size="64" /><el-table v-else :data="assets" size="small"><el-table-column prop="originalFilename" label="文件名" min-width="180" /><el-table-column prop="assetType" label="类型" width="100" /><el-table-column label="存储卷 / 位置" min-width="260" show-overflow-tooltip><template #default="{ row }"><div>{{ row.storageVolumeName || row.storageVolumeId || '-' }}<span v-if="row.storageTier"> · {{ statusLabel(row.storageTier) }}</span></div><small>{{ row.storageKey || '-' }}</small><small v-if="row.storageAccessible === false">{{ row.storageUnavailableReason || '存储卷不可访问' }}</small><small v-if="row.storageDiagnosticReason">副本诊断：{{ row.storageDiagnosticReason }}</small><small v-if="row.storageAccessible === false && offlineStorageSummary(row)">冷备定位：{{ offlineStorageSummary(row) }}</small></template></el-table-column><el-table-column label="存储状态" width="110"><template #default="{ row }"><status-badge :value="storageMountState(row)" /></template></el-table-column></el-table></el-col><el-col :span="10"><h4>补传工程文件 <el-tag size="small" type="info" effect="plain">仅本地</el-tag></h4><el-upload :auto-upload="false" :show-file-list="false" :on-change="uploadFile"><el-button plain :loading="supplementUpload.status === 'UPLOADING'"><el-icon><FolderAdd /></el-icon>选择文件上传</el-button></el-upload><div v-if="supplementUpload.status !== 'IDLE'" class="supplement-progress"><div class="progress-line"><span>{{ supplementUpload.message }}</span><strong>{{ supplementUpload.percent }}%</strong></div><el-progress :percentage="supplementUpload.percent" :status="supplementUpload.status === 'FAILED' ? 'exception' : supplementUpload.status === 'SUCCEEDED' ? 'success' : undefined" :stroke-width="8" /><small v-if="supplementUpload.jobId">任务 {{ supplementUpload.jobId }} · <status-badge :value="supplementUpload.status" /></small></div><div v-if="!supplements.length" class="empty-mini">尚无补传文件</div><div v-for="file in supplements" :key="file.fileId" class="supplement-row"><div><strong>{{ file.fileName }}</strong><small>{{ file.size }} bytes</small><small>{{ file.storageVolumeName || file.storageVolumeId || '-' }}<span v-if="file.storageTier"> · {{ statusLabel(file.storageTier) }}</span><span v-if="file.storageMountStatus"> · {{ statusLabel(file.storageMountStatus) }}</span> · {{ file.storageKey || '未记录位置' }}</small><small v-if="file.storageAccessible === false">{{ file.storageUnavailableReason || '存储卷不可访问' }}</small></div><el-button link type="primary" :disabled="file.storageAccessible === false" @click="downloadSupplement(file)">下载</el-button></div></el-col></el-row>
  </el-card>
</template>
